fs::path sdroot; int audio_calls=0; int get_name_mode=0;
struct FileState {fs::path path;bool open=false;size_t cursor=0;std::vector<fs::path> entries;};
struct FsFile {
 std::shared_ptr<FileState> s=std::make_shared<FileState>();
 bool open(const char *name,int mode=0){if(mode)throw std::runtime_error("writes forbidden");s=std::make_shared<FileState>();fs::path q(name);s->path=sdroot/q.relative_path();s->open=fs::exists(s->path);if(s->open&&fs::is_directory(s->path)){for(auto &e:fs::directory_iterator(s->path))s->entries.push_back(e.path());std::sort(s->entries.begin(),s->entries.end());}return s->open;}
 bool openNext(FsFile *dir,int=0){if(dir->s->cursor>=dir->s->entries.size()){s=std::make_shared<FileState>();return false;}auto p=dir->s->entries[dir->s->cursor++];return open(fs::relative(p,sdroot).generic_string().c_str());}
 void close(){s->open=false;} bool isOpen()const{return s->open;} bool isDirectory()const{return s->open&&fs::is_directory(s->path);} bool isReadable()const{return s->open&&!isDirectory();} bool isWritable()const{return false;}
 int getError()const{return 0;} size_t getName(char *dst,size_t n)const{if(!s->open)return 0;auto a=s->path.filename().string();if(n){std::strncpy(dst,a.c_str(),n-1);dst[n-1]=0;}return get_name_mode==2 && a.size()>=n ? 0 : (get_name_mode==1 ? std::min(a.size(),n-1) : a.size());}
 uint64_t fileSize()const{return isReadable()?fs::file_size(s->path):0;} uint64_t size()const{return fileSize();}
 void rewindDirectory(){s->cursor=0;}void rewind(){s->cursor=0;}void seekSet(uint64_t x){s->cursor=size_t(x);}void seekCur(uint64_t x){s->cursor+=size_t(x);}
 int read(uint8_t *d,size_t n){if(!isReadable())return 0;std::ifstream in(s->path,std::ios::binary);in.seekg(s->cursor);in.read((char*)d,n);auto k=in.gcount();s->cursor+=size_t(k);return int(k);}
 void write(const uint8_t*,size_t){throw std::runtime_error("writes forbidden");}void truncate(){}void sync(){}int getWriteError(){return 0;}void clearWriteError(){}
};
struct SDType {bool mkdir(const char*){throw std::runtime_error("mkdir forbidden");}bool chdir(const char*){return true;}} SD;
struct image_config_t {int scsiId=0,deviceType=2;bool ejected=false,reinsert_after_eject=false,use_prefix=false;int cdrom_events=0;std::string opened;std::vector<std::string> cycle;int cycle_index=0;FsFile file;int getTargetId()const{return scsiId;}};
