static bool toolboxFilenameValid(const char* name, const bool isCD = false)
{
    if(strlen(name) == 0)
    {
        dbgmsg("toolbox: Ignoring filename empty file name");
        return false;
    }
    if(name[0] == '.')
    {
        dbgmsg("toolbox: Ignoring hidden file ", name);
        return false;
    }
    if (isCD)
    {
      return scsiDiskFilenameValid(name);
    }
    return true;
}

static void doCountFiles(const char * dir_name, bool isCD = false)
{
    FsFile dir;
    FsFile file;
    char name[MAX_FILE_PATH] = {0};
    if (!dir.open(dir_name)) {
        if (!isCD && (!SD.mkdir(dir_name) || !dir.open(dir_name))) {
            logmsg("ERROR: Could not open or create BlueSCSI Toolbox shared dir: ", dir_name);
            scsiDev.status = CHECK_CONDITION;
            scsiDev.target->sense.code = ILLEGAL_REQUEST;
            scsiDev.phase = STATUS;
            return;
        }
    }
    dir.rewindDirectory();
    uint8_t file_count = 0;
    while (file.openNext(&dir, O_RDONLY))
    {
        if(file.getError() > 0)
        {
            file.close();
            break;
        }
        bool isDir = file.isDirectory();
        size_t len = file.getName(name, MAX_FILE_PATH);
        file.close();
        if (isCD && isDir)
            continue;
        // truncate filename the same way listing does, before validating name
        if (len > MAX_MAC_PATH)
            name[MAX_MAC_PATH] = 0x0;
        dbgmsg("TOOLBOX COUNT FILES: truncated filename is '", name, "'");
        // only count valid files.
        if(toolboxFilenameValid(name, isCD))
        {
            file_count = file_count + 1;
            if(file_count > MAX_FILE_LISTING_FILES) {
                scsiDev.status = CHECK_CONDITION;
                scsiDev.target->sense.code = ILLEGAL_REQUEST;
                scsiDev.target->sense.asc = OPEN_RETRO_SCSI_TOO_MANY_FILES;
                scsiDev.phase = STATUS;
                dir.close();
                return;
            }
        }
  }
  scsiDev.data[0] = file_count;
  scsiDev.dataLen = sizeof(file_count);
  scsiDev.phase = DATA_IN;
}

static void onListFiles(const char * dir_name, bool isCD = false) {
    FsFile dir;
    FsFile file;

    memset(scsiDev.data, 0, ENTRY_SIZE * (MAX_FILE_LISTING_FILES + 1));
    char name[MAX_FILE_PATH] = {0};
    uint8_t index = 0;
    uint8_t file_entry[ENTRY_SIZE] = {0};

    if (!dir.open(dir_name)) {
        if (!isCD && (!SD.mkdir(dir_name) || !dir.open(dir_name))) {
            logmsg("ERROR: Could not open or create BlueSCSI Toolbox shared dir: ", dir_name);
            scsiDev.status = CHECK_CONDITION;
            scsiDev.target->sense.code = ILLEGAL_REQUEST;
            scsiDev.phase = STATUS;
            return;
        }
    }
    dir.rewindDirectory();
    while (file.openNext(&dir, O_RDONLY))
    {   
        memset(name, 0, sizeof(name));
        // get base information
        uint8_t isDir = file.isDirectory() ? 0x00 : 0x01;
        size_t len = file.getName(name, MAX_FILE_PATH);
        uint64_t size = file.fileSize();
        file.close();
        // validate file is allowed for this listing
        if (!toolboxFilenameValid(name, isCD))
            continue;
        if (isCD && isDir == 0x00)
            continue;
        // truncate filename to fit in destination buffer
        if (len > MAX_MAC_PATH)
            name[MAX_MAC_PATH] = 0x0;
        dbgmsg("TOOLBOX LIST FILES: truncated filename is '", name, "'");
        // fill output buffer
        file_entry[0] = index;
        file_entry[1] = isDir;
        for(int i = 0; i < MAX_MAC_PATH + 1 ; i++) {
            file_entry[i + 2] = name[i];   // bytes 2 - 34
        }
        file_entry[35] = (size >> 32) & 0xff;
        file_entry[36] = (size >> 24) & 0xff;
        file_entry[37] = (size >> 16) & 0xff;
        file_entry[38] = (size >> 8) & 0xff;
        file_entry[39] = (size) & 0xff;
        // send to SCSI output buffer
        memcpy(&(scsiDev.data[ENTRY_SIZE * index]), file_entry, ENTRY_SIZE);
        // increment index
        index = index + 1;
        if (index >= MAX_FILE_LISTING_FILES) break;
    }
    dir.close();

    scsiDev.dataLen = ENTRY_SIZE * index;
    scsiDev.phase = DATA_IN;
    dbgmsg("TOOLBOX LIST FILES: returning ", index, " files for size ", scsiDev.dataLen);
}

static FsFile get_file_from_index(uint8_t index, const char * dir_name, bool isCD = false)
{
    FsFile dir;
    FsFile file_test;
    char name[MAX_FILE_PATH] = {0};

    dir.open(dir_name);
    dir.rewindDirectory(); // Back to the top
    int count = 0;
    while (file_test.openNext(&dir, O_RDONLY))
    {
        // If error there is no next file to open.
        if(file_test.getError() > 0) {
            file_test.close();
            break;
        }
        // no directories in CD image listing
        if (isCD && file_test.isDirectory())
        {
            file_test.close();
            continue;
        }
        // truncate filename the same way listing does, before validating name
        size_t len = file_test.getName(name, MAX_FILE_PATH);
        if (len > MAX_MAC_PATH)
            name[MAX_MAC_PATH] = 0x0;
        // validate filename
        if(!toolboxFilenameValid(name, isCD))
        {
            file_test.close();
            continue;
        }
        // found file?
        if (count == index)
        {
            dir.close();
            return file_test;
        }
        else
        {
            file_test.close();
        }
        count++;
    }
    file_test.close();
    dir.close();
    return file_test;
}

// Devices that are active on this SCSI device.
static void onListDevices()
{
    for (int i = 0; i < NUM_SCSIID; i++)
    {
        const S2S_TargetCfg* cfg = s2s_getConfigById(i);
        if (cfg && s2s_isTargetEnabled(cfg))
        {
            scsiDev.data[i] = static_cast<int>(cfg->deviceType); // 2 == cd
        }
        else
        {
            scsiDev.data[i] = 0xFF; // not enabled target.
        }
    }
    scsiDev.dataLen = NUM_SCSIID;
    scsiDev.phase = DATA_IN;
}

// Returns API version and capability flags
static void onGetCapabilities()
{
    memset(scsiDev.data, 0, 8);
    scsiDev.data[0] = TOOLBOX_API_VERSION;
    scsiDev.data[1] = TOOLBOX_CAP_LARGE_TRANSFERS | TOOLBOX_CAP_LARGE_SEND | TOOLBOX_CAP_SET_WORKING_DIR;
    // bytes 2-7 reserved
    scsiDev.dataLen = 8;
    scsiDev.phase = DATA_IN;
}

// Set the working directory for file operations
static void onSetWorkingDir()
{
    uint8_t path_len = scsiDev.cdb[8];

    // Parameter list length of zero: no data to transfer, no state change.
    // Matches SCSI-2 convention used by MODE SELECT. Clients that want to
    // reset the override must send a 1-byte NUL path explicitly.
    if (path_len == 0)
    {
        dbgmsg("TOOLBOX SET_WORKING_DIR: zero-length, no change");
        scsiDev.phase = STATUS;
        return;
    }

    if (path_len > 64) path_len = 64;

    char path[65] = {0};
    scsiEnterPhase(DATA_OUT);
    scsiRead(reinterpret_cast<uint8_t*>(path), path_len, NULL);
    path[path_len] = '\0';

    if (path[0] == '\0')
    {
        // Empty C string reset to default
        g_toolbox_dir_override[0] = '\0';
        dbgmsg("TOOLBOX SET_WORKING_DIR: reset to default");
    }
    else
    {
        strncpy(g_toolbox_dir_override, path, MAX_FILE_PATH - 1);
        g_toolbox_dir_override[MAX_FILE_PATH - 1] = '\0';
        dbgmsg("TOOLBOX SET_WORKING_DIR: '", g_toolbox_dir_override, "'");
    }

    scsiDev.phase = STATUS;
}

// Get the current working directory for file operations
static void onGetWorkingDir()
{
    char dir_name[MAX_FILE_PATH] = {0};
    getEffectiveDir(dir_name);

    uint8_t alloc_len = scsiDev.cdb[8];
    if (alloc_len == 0) alloc_len = MAX_FILE_PATH;
    if (alloc_len > MAX_FILE_PATH) alloc_len = MAX_FILE_PATH;

    size_t path_len = strlen(dir_name) + 1; // include null terminator
    if (path_len > alloc_len) path_len = alloc_len;

    memset(scsiDev.data, 0, alloc_len);
    memcpy(scsiDev.data, dir_name, path_len);
    scsiDev.dataLen = alloc_len;
    scsiDev.phase = DATA_IN;

    dbgmsg("TOOLBOX GET_WORKING_DIR: '", dir_name, "'");
}

// Handle 0xD9 metadata command with subcommands
// CDB[1] = subcommand
// CDB[8] = allocation length (0 = 8 for backward compatibility)
static void onMetadataCommand()
{
    uint8_t subcommand = scsiDev.cdb[1];

    // SET_WORKING_DIR uses CDB[8] as data length, not allocation length
    if (subcommand == TOOLBOX_SUBCMD_SET_WORKING_DIR)
    {
        dbgmsg("TOOLBOX_METADATA: SET_WORKING_DIR");
        onSetWorkingDir();
        return;
    }

    if (subcommand == TOOLBOX_SUBCMD_GET_WORKING_DIR)
    {
        dbgmsg("TOOLBOX_METADATA: GET_WORKING_DIR");
        onGetWorkingDir();
        return;
    }

    uint8_t alloc_len = scsiDev.cdb[8];

    // Treat 0 as 8 for backward compatibility with older clients
    if (alloc_len == 0)
    {
        alloc_len = 8;
    }

    // Currently max response is 8 bytes
    if (alloc_len > 8)
    {
        dbgmsg("TOOLBOX_METADATA: allocation length ", alloc_len, " exceeds maximum 8");
        scsiDev.status = CHECK_CONDITION;
        scsiDev.target->sense.code = ILLEGAL_REQUEST;
        scsiDev.phase = STATUS;
        return;
    }

    switch (subcommand)
    {
        case TOOLBOX_SUBCMD_LIST_DEVICES:
            dbgmsg("TOOLBOX_METADATA: LIST_DEVICES");
            onListDevices();
            // Truncate to requested allocation length
            if (scsiDev.dataLen > alloc_len)
                scsiDev.dataLen = alloc_len;
            break;
        case TOOLBOX_SUBCMD_GET_CAPABILITIES:
            dbgmsg("TOOLBOX_METADATA: GET_CAPABILITIES");
            onGetCapabilities();
            // Truncate to requested allocation length
            if (scsiDev.dataLen > alloc_len)
                scsiDev.dataLen = alloc_len;
            break;
        default:
            dbgmsg("TOOLBOX_METADATA: Unknown subcommand ", subcommand);
            scsiDev.status = CHECK_CONDITION;
            scsiDev.target->sense.code = ILLEGAL_REQUEST;
            scsiDev.phase = STATUS;
            break;
    }
}

static void onSetNextCD(const char * img_dir)
{
    char name[MAX_FILE_PATH] = {0};
    char full_path[MAX_FILE_PATH * 2] = {0};
    uint8_t file_index = scsiDev.cdb[1];
    image_config_t &img = *(image_config_t*)scsiDev.target->cfg;
    FsFile next_cd = get_file_from_index(file_index, img_dir, true);
    next_cd.getName(name, sizeof(name));
    next_cd.close();
    snprintf(full_path, (MAX_FILE_PATH * 2), "%s/%s", img_dir, name);
    switchNextImage(img, full_path);
}

FsFile gFile; // global so we can keep it open while transferring.
void onGetFile10(char * dir_name) {
    uint8_t index = scsiDev.cdb[1];

    uint32_t offset = ((uint32_t)scsiDev.cdb[2] << 24) | ((uint32_t)scsiDev.cdb[3] << 16) | ((uint32_t)scsiDev.cdb[4] << 8) | scsiDev.cdb[5];

    // CDB byte 6: number of 4K blocks to transfer (0 = 1 for backward compatibility)
    uint8_t block_count = scsiDev.cdb[6];
    if (block_count == 0) block_count = 1;

    if (offset == 0) // first time, open the file.
    {
        // Safety: ensure gFile is closed from any previous operation
        if (gFile.isOpen()) {
            gFile.close();
        }
        gFile = get_file_from_index(index, dir_name);
        if(!gFile.isDirectory() && !gFile.isReadable())
        {
            scsiDev.status = CHECK_CONDITION;
            scsiDev.target->sense.code = ILLEGAL_REQUEST;
            //SCSI_ASC_INVALID_FIELD_IN_CDB
            scsiDev.phase = STATUS;
            return;
        }
    }

    uint32_t file_total = gFile.size();
    uint32_t byte_offset = offset * 4096;
    uint32_t bytes_requested = (uint32_t)block_count * 4096;

    // Cap to remaining file size
    if (byte_offset + bytes_requested > file_total) {
        bytes_requested = (byte_offset < file_total) ? (file_total - byte_offset) : 0;
    }

    // Cap to buffer size
    if (bytes_requested > sizeof(scsiDev.data)) {
        bytes_requested = sizeof(scsiDev.data);
    }

    memset(scsiDev.data, 0, bytes_requested);
    gFile.seekSet(byte_offset);
    int bytes_read = gFile.read(scsiDev.data, bytes_requested);
    if(byte_offset + bytes_read >= file_total) // transfer done, close.
    {
        gFile.close();
    }
    scsiDev.dataLen = bytes_read;
    scsiDev.phase = DATA_IN;
}

/*
  Prepares a file for receiving. The file name is null terminated in the scsi data.
*/
static void onSendFilePrep(char * dir_name)
{
    char file_name[32+1];

    scsiEnterPhase(DATA_OUT);
    scsiRead(static_cast<uint8_t *>(static_cast<void *>(file_name)), 32+1, NULL);
    file_name[32] = '\0';

    dbgmsg("TOOLBOX OPEN FILE FOR WRITE: '", file_name, "'");
    if (!SD.chdir(dir_name))
    {
        if (!SD.mkdir(dir_name) || !SD.chdir(dir_name))
        {
            logmsg("ERROR: Could not open or create BlueSCSI Toolbox shared dir: ", dir_name);
            scsiDev.status = CHECK_CONDITION;
            scsiDev.target->sense.code = ILLEGAL_REQUEST;
            scsiDev.phase = STATUS;
            return;
        }
    }
    gFile.open(file_name, FILE_WRITE);
    SD.chdir("/");
    if(gFile.isOpen() && gFile.isWritable())
    {
        gFile.rewind();
        gFile.truncate();
        gFile.sync();
        // do i need to manually set phase to status here?
        return;
    } else {
        gFile.close();
        scsiDev.status = CHECK_CONDITION;
        scsiDev.target->sense.code = ILLEGAL_REQUEST;
        //SCSI_ASC_INVALID_FIELD_IN_CDB
        scsiDev.phase = STATUS;
    }
}

static void onSendFileEnd(void)
{
    gFile.sync();
    gFile.close();
    scsiDev.phase = STATUS;
}

static void onSendFile10(void)
{
    if(!gFile.isOpen() || !gFile.isWritable())
    {
        scsiDev.status = CHECK_CONDITION;
        scsiDev.target->sense.code = ILLEGAL_REQUEST;
        //SCSI_ASC_INVALID_FIELD_IN_CDB
        scsiDev.phase = STATUS;
        return;
    }

    // CDB[6] = block count for new block-based encoding (0 = use legacy CDB[1-2])
    uint8_t block_count = scsiDev.cdb[6];
    uint16_t bytes_sent;
    if (block_count > 0)
    {
        // New block-based encoding: transfer size = CDB[6] × 512 bytes
        bytes_sent = (uint16_t)block_count * 512;
    }
    else
    {
        // Legacy encoding: Number of bytes sent this request, 1..65535
        bytes_sent = ((uint16_t)scsiDev.cdb[1] << 8) | scsiDev.cdb[2];
    }
    // 512 byte offset of where to put these bytes.
    uint32_t offset     = ((uint32_t)scsiDev.cdb[3] << 16) | ((uint32_t)scsiDev.cdb[4] << 8) | scsiDev.cdb[5];

    // Do not allow buffer overrun
    if (bytes_sent > sizeof(scsiDev.data))
    {
        dbgmsg("TOOLBOX SEND FILE 10 ILLEGAL DATA SIZE");
        gFile.close();
        scsiDev.status = CHECK_CONDITION;
        scsiDev.target->sense.code = ILLEGAL_REQUEST;
        scsiDev.phase = STATUS;
        return;
    }

    scsiEnterPhase(DATA_OUT);
    scsiRead(scsiDev.data, bytes_sent, NULL);
    gFile.seekCur(offset * 512);
    gFile.write(scsiDev.data, bytes_sent);
    if(gFile.getWriteError())
    {
        gFile.clearWriteError();
        gFile.close();
        scsiDev.status = CHECK_CONDITION;
        scsiDev.target->sense.code = ILLEGAL_REQUEST;
        scsiDev.phase = STATUS;
        return;
    }
    //scsiDev.phase = STATUS;
}
static void onToggleDebug()
{
    if(scsiDev.cdb[1] == 0) // 0 == Set Debug, 1 == Get Debug State
    {
        g_log_debug = scsiDev.cdb[2];
        logmsg("Set debug logs to: ", g_log_debug);
        scsiDev.phase = STATUS;
    }
    else
    {
        logmsg("Debug currently set to: ", g_log_debug);
        scsiDev.data[0] = g_log_debug ? 0x1 : 0x0;
        scsiDev.dataLen = 1;
        scsiDev.phase = DATA_IN;
    }
}

static int getToolBoxSharedDir(char * dir_name)
{
  return ini_gets("SCSI", "ToolBoxSharedDir", "/shared", dir_name, MAX_FILE_PATH, CONFIGFILE);
}

extern "C" int scsiToolboxCommand()
{
    int commandHandled = 1;
    image_config_t &img = *(image_config_t*)scsiDev.target->cfg;
    uint8_t command = scsiDev.cdb[0];

    if (unlikely(command == BLUESCSI_TOOLBOX_COUNT_FILES))
    {
        char img_dir[MAX_FILE_PATH];
        dbgmsg("BLUESCSI_TOOLBOX_COUNT_FILES");
        getEffectiveDir(img_dir);
        doCountFiles(img_dir);
    }
    else if (unlikely(command == BLUESCSI_TOOLBOX_LIST_FILES))
    {
        char img_dir[MAX_FILE_PATH];
        dbgmsg("BLUESCSI_TOOLBOX_LIST_FILES");
        getEffectiveDir(img_dir);
        onListFiles(img_dir);
    }
    else if (unlikely(command == BLUESCSI_TOOLBOX_GET_FILE))
    {
        char img_dir[MAX_FILE_PATH];
        dbgmsg("BLUESCSI_TOOLBOX_GET_FILE");
        getEffectiveDir(img_dir);
        onGetFile10(img_dir);
    }
    else if (unlikely(command == BLUESCSI_TOOLBOX_SEND_FILE_PREP))
    {
        char img_dir[MAX_FILE_PATH];
        dbgmsg("BLUESCSI_TOOLBOX_SEND_FILE_PREP");
        getEffectiveDir(img_dir);
        onSendFilePrep(img_dir);
    }
    else if (unlikely(command == BLUESCSI_TOOLBOX_SEND_FILE_10))
    {
        dbgmsg("BLUESCSI_TOOLBOX_SEND_FILE_10");
        onSendFile10();
    }
    else if (unlikely(command == BLUESCSI_TOOLBOX_SEND_FILE_END))
    {
        dbgmsg("BLUESCSI_TOOLBOX_SEND_FILE_END");
        onSendFileEnd();
    }
    else if(unlikely(command == BLUESCSI_TOOLBOX_TOGGLE_DEBUG))
    {
        dbgmsg("BLUESCSI_TOOLBOX_TOGGLE_DEBUG");
        onToggleDebug();
    }
    else if(unlikely(command == BLUESCSI_TOOLBOX_LIST_CDS))
    {
        char img_dir[4]; // "CDF" + NUL
        dbgmsg("BLUESCSI_TOOLBOX_LIST_CDS");
        snprintf(img_dir, sizeof(img_dir), CD_IMG_DIR, scsiEncodeID(img.getTargetId()));
        onListFiles(img_dir, true);
    }
    else if(unlikely(command == BLUESCSI_TOOLBOX_SET_NEXT_CD))
    {
        char img_dir[4]; // "CDF" + NUL
        dbgmsg("BLUESCSI_TOOLBOX_SET_NEXT_CD");
        snprintf(img_dir, sizeof(img_dir), CD_IMG_DIR, scsiEncodeID(img.getTargetId()));
        onSetNextCD(img_dir);
    }
    else if(unlikely(command == BLUESCSI_TOOLBOX_METADATA))
    {
        dbgmsg("BLUESCSI_TOOLBOX_METADATA");
        onMetadataCommand();
    }
    else if (unlikely(command == BLUESCSI_TOOLBOX_COUNT_CDS))
    {
        char img_dir[4]; // "CDF" + NUL
        dbgmsg("BLUESCSI_TOOLBOX_COUNT_CDS");
        snprintf(img_dir, sizeof(img_dir), CD_IMG_DIR, scsiEncodeID(img.getTargetId()));
        doCountFiles(img_dir, true);
    }
    else
    {
        commandHandled = 0;
    }

    return commandHandled;
}

